UPDATE resource_cloud_receipts SET uploaded_at=IF(?=1,UNIX_TIMESTAMP(),IF(cloud_path=? AND checksum=? AND confirmed_content_generation=? AND confirmed_target_revision=?,uploaded_at,NULL)),task_state='succeeded',cloud_path=?,checksum=?,size_bytes=?,confirmed_content_generation=?,confirmed_target_revision=?,verified_at=UNIX_TIMESTAMP(),verification=?,verification_method=?,remote_hash_algorithm=?,remote_hash_value=?,source_adapter=?,attempt=NULL,transfer_policy='normal',path_unresolved=0,result_code='ok',error_category='',running_batch_id='',claimed_at=0,updated_at=UNIX_TIMESTAMP()
WHERE owner_type=? AND resource_id=? AND cloud_provider=? AND claim_generation=? AND running_batch_id=? AND content_generation=? AND target_revision=?
